SELECT a.attend_id, a.student_id, a.attend_date, a.attend_status, a.note, a.reg_date, s.student_num, s.student_name, s.dept_name FROM TB_ATTEND a INNER JOIN TB_STUDENT s ON a.student_id = s.student_id WHERE s.del_yn = 'N'
AND a.student_id = #{studentId}
AND (s.student_name LIKE CONCAT('%', #{searchKeyword}, '%') OR s.student_num LIKE CONCAT('%', #{searchKeyword}, '%'))
AND a.attend_status = #{searchStatus}
AND a.attend_date >= #{startDate}
AND a.attend_date <= #{endDate}
ORDER BY a.attend_date DESC, s.student_num ASC LIMIT #{pageSize} OFFSET #{offset}

