SELECT COUNT(*)
FROM TB_ATTEND
WHERE student_id  = #{studentId}
  AND attend_date = #{attendDate}

    AND attend_id != #{attendId}

SELECT student_id, COUNT(*) AS total_count, SUM(CASE WHEN attend_status = '출석' THEN 1 ELSE 0 END) AS present_count, SUM(CASE WHEN attend_status = '지각' THEN 1 ELSE 0 END) AS late_count, SUM(CASE WHEN attend_status = '결석' THEN 1 ELSE 0 END) AS absent_count, SUM(CASE WHEN attend_status = '공결' THEN 1 ELSE 0 END) AS official_count, ROUND( (SUM(CASE WHEN attend_status IN ('출석','공결') THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0)) * 100 , 1) AS attend_rate FROM TB_ATTEND WHERE student_id = #{studentId}
AND attend_date >= #{startDate}
AND attend_date <= #{endDate}
